test_that("boolalg: test_distribute matches SymPy", {
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); distribute_and_over_or(Or(And(A, B), C)) })), "(A | C) & (B | C)")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); distribute_or_over_and(And(A, Or(B, C))) })), "(A & B) | (A & C)")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); distribute_xor_over_and(And(A, Xor(B, C))) })), "(A & B) ^ (A & C)")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); distribute_and_over_or(Or(And(A, B), And(C, D))) })), "(A | C) & (A | D) & (B | C) & (B | D)")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); distribute_or_over_and(And(Or(A, B), Or(C, D))) })), "(A & C) | (A & D) | (B & C) | (B & D)")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); distribute_xor_over_and(And(Xor(A, B), Xor(C, D))) })), "(A & C) ^ (A & D) ^ (B & C) ^ (B & D)")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); distribute_and_over_or(A) })), "A")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); distribute_and_over_or(And(A, Or(B, C))) })), "A & (B | C)")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); distribute_or_over_and(Or(A, And(B, C))) })), "A | (B & C)")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); distribute_xor_over_and(And(A, B)) })), "A & B")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); distribute_xor_over_and(Xor(A, And(B, Xor(C, D)))) })), "A ^ (B & C) ^ (B & D)")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); distribute_and_over_or(Or(A, And(B, Or(C, D)))) })), "(A | B) & (A | C | D)")
})

test_that("boolalg: test_to_anf matches SymPy", {
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); to_anf(And(x, y)) })), "x & y")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); to_anf(Or(x, y)) })), "x ^ y ^ (x & y)")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); to_anf(Or(Implies(x, y), And(x, y), y)) })), "x ^ True ^ (x & y)")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); to_anf(Or(Nand(x, y), Nor(x, y), Xnor(x, y), Implies(x, y))) })), "True")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); to_anf(Or(x, Not(y), Nor(x, z), And(x, y), Nand(y, z))) })), "True ^ (y & z) ^ (x & y & z)")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); to_anf(Xor(x, y)) })), "x ^ y")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); to_anf(Not(x)) })), "x ^ True")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); to_anf(Nand(x, y)) })), "True ^ (x & y)")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); to_anf(Nor(x, y)) })), "x ^ y ^ True ^ (x & y)")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); to_anf(Implies(x, y)) })), "x ^ True ^ (x & y)")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); to_anf(Equivalent(x, y)) })), "x ^ y ^ True")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); to_anf(Nand(Or(x, y), Implies(x, y)), deep = FALSE) })), "True ^ ((Implies(x, y)) & (x | y))")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); to_anf(Nor(Xor(x, y), And(x, y)), deep = FALSE) })), "True ^ ((x & y) | (x ^ y))")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); to_anf(Xor(x, Not(Xor(x, y, Not(y))))) })), "False")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); to_anf(Or(x, y, z)) })), "x ^ y ^ z ^ (x & y) ^ (x & z) ^ (y & z) ^ (x & y & z)")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); to_anf(And(x, Or(y, z))) })), "(x & y) ^ (x & z) ^ (x & y & z)")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); to_anf(Equivalent(x, y, z)) })), "x ^ y ^ z ^ True ^ (x & y) ^ (x & z) ^ (y & z)")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); to_anf(Implies(x, Or(y, z))) })), "x ^ True ^ (x & y) ^ (x & z) ^ (x & y & z)")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); to_anf(Xor(Not(x), y)) })), "x ^ y ^ True")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); to_anf(And(Not(x), Not(y))) })), "x ^ y ^ True ^ (x & y)")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); to_anf(S_true) })), "True")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); to_anf(x) })), "x")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); to_anf(Or(x, y), deep = FALSE) })), "x ^ y ^ (x & y)")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); to_anf(ITE(x, y, z)) })), "ITE(x, y, z)")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); to_anf(Not(And(x, Or(y, z)))) })), "True ^ (x & y) ^ (x & z) ^ (x & y & z)")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); to_anf(Equivalent(x, And(y, z))) })), "x ^ True ^ (y & z)")
})

