test_that("boolalg: test_gateinputcount matches SymPy", {
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); gateinputcount(And(a, b)) })), "2")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); gateinputcount(Or(a, Xor(And(b, c, d), Or(e, a)))) })), "9")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); gateinputcount(And(a, TRUE)) })), "0")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); gateinputcount(a * b) })), "ERR TypeError: Expression must be Boolean")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); gateinputcount(a) })), "0")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); gateinputcount(Not(a)) })), "1")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); gateinputcount(ITE(a, b, Not(c))) })), "4")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); gateinputcount(Implies(a, b)) })), "0")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); gateinputcount(Or(And(a, b), And(Not(a), c), Xor(b, c))) })), "10")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); gateinputcount(Lt(a, 1)) })), "0")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); gateinputcount(Nand(a, b, c)) })), "4")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); gateinputcount(Xnor(a, b)) })), "3")
